    empty.environments.register(task('swe-task:empty-held-out', '', true))
    expect(() => empty.environments.register(task('swe-task:empty-other', '   ', false)))
      .toThrow(expect.objectContaining({ code: 'ENVIRONMENT_NEAR_DUPLICATE' }))
  })

